function generateRandomHex(length) {
  const chars = '0123456789abcdef';
  let result = '';
  for (let i = 0; i < length; i++) {
    result += chars[Math.floor(Math.random() * chars.length)];
  }
  return result;
}

const body = $input.first().json.body || $input.first().json;

const region = body.region;
const connectionName = body.connectionName;
const roleName = body.roleName || 'FinOpsAwsIntegrationRole';
const stackName = body.stackName || (connectionName || 'AWS').replace(/[^a-zA-Z0-9-]/g, '-');
const userId = body.userId || 'default_user';
const awsAccountId = body.awsAccountId;
const provider = body.provider || 'aws';
const setupMethod = body.setupMethod || 'cloudformation';
const platformAccountId = body.platformAccountId || '864981730114';
const templateUrl = body.templateUrl || 'https://square-pulse-public.s3.ap-south-1.amazonaws.com/templates/finops-aws-cloud-cost-role.yaml';

const connectionId = body.connectionId || `conn_${generateRandomHex(12)}`;
const externalId = body.externalId || `ext_${generateRandomHex(24)}`;

const queryParts = [
  'templateURL=' + encodeURIComponent(templateUrl),
  'stackName=' + encodeURIComponent(stackName),
  'param_PlatformAccountId=' + encodeURIComponent(platformAccountId),
  'param_ExternalId=' + encodeURIComponent(externalId),
  'param_IAMRoleName=' + encodeURIComponent(roleName)
];

const queryString = queryParts.join('&');
const cloudFormationLaunchUrl = `https://${region}.console.aws.amazon.com/cloudformation/home?region=${region}#/stacks/quickcreate?${queryString}`;

return {
  userId,
  connectionId,
  externalId,
  platformAccountId,
  awsAccountId,
  roleName,
  stackName,
  region,
  connectionName,
  cloudFormationLaunchUrl,
  provider,
  setupMethod,
  status: 'cloudformation_pending',
  roleStatus: 'unverified',
  createdAt: new Date().toISOString()
};
